if (!defined('WB_API')) { http_response_code(404); exit; }
function wb_allowed_types() { return array('jpg' => 'image/jpeg', 'png' => 'image/png', 'gif' => 'image/gif', 'webp' => 'image/webp', 'mp4' => 'video/mp4', 'webm' => 'video/webm'); }   /* SVG 는 스크립트를 담을 수 있어 업로드 금지 (관리자와 같은 주소에서 열리므로) */
function wb_uploads_dir() { return WB_WEB_ROOT . '/assets/uploads'; }
function wb_media_out($m, $base) { $v = wb_arr($m['variants_json']); $url = $base . '/uploads/' . (!empty($v['src']) ? $v['src'] : $m['filename']); return array('id' => (int)$m['id'], 'name' => $m['original_name'], 'alt' => (string)$m['alt'], 'mime' => $m['mime'], 'size' => (int)$m['size'], 'width' => $m['width'] === null ? null : (int)$m['width'], 'height' => $m['height'] === null ? null : (int)$m['height'], 'url' => $url, 'thumb' => !empty($v['thumb']) ? $base . '/uploads/' . $v['thumb'] : $url, 'mobile' => !empty($v['mobile']) ? $base . '/uploads/' . $v['mobile'] : $url, 'pc' => $url, 'original' => !empty($v['original']) ? $base . '/uploads/' . $v['original'] : $url, 'folder_id' => $m['folder_id'] ? (int)$m['folder_id'] : null, 'usage' => 0, 'created_at' => $m['created_at'], 'is_image' => strpos($m['mime'], 'image/') === 0, 'kind' => $m['kind'] ? $m['kind'] : (strpos($m['mime'], 'video/') === 0 ? 'video' : 'image'), 'variants' => (object)$v, 'duration' => $m['duration'] === null ? null : (float)$m['duration']); }
function wb_media_of($c, $id, $ability = 'view') { $m = wb_get('SELECT * FROM media WHERE id = ? AND deleted_at IS NULL', array((int)$id)); if (!$m) { throw new WbHttpError(404, '파일을 찾을 수 없습니다.'); } wb_site_of($c, (int)$m['site_id'], $ability); return $m; }
function wb_file_by_field($c, $field) { foreach ($c['files'] as $f) { if ($f['field'] === $field) { return $f; } } return null; }
function wb_store_upload($c, $s, $file, $opts = array()) {
